pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.deal(user, 10 ether);

        vm.prank(user);
        c.Deposit{value: 2 ether}();

        uint balanceBefore = c.balances(user);

        bool ok;
        vm.prank(user);
        try c.CashOut(balanceBefore) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: ok is true (withdrawal succeeds) and balance becomes 0
        // Bug: ok is false (withdrawal reverts) and balance stays 2 ether
        assertTrue(ok == true); // This assertion passes on reference but fails on bug
