pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // user1: deposit exactly MinDeposit (1 ether) – reference rejects, bug accepts
        // user2: deposit 2 ether (above MinDeposit) – accepted by both
        address user1 = address(0x123);
        address user2 = address(0x456);

        vm.deal(user1, 1 ether);
        vm.deal(user2, 2 ether);

        // user1 attempts deposit of exactly 1 ether
        vm.prank(user1);
        c.Deposit{value: 1 ether}();

        // user2 deposits 2 ether
        vm.prank(user2);
        c.Deposit{value: 2 ether}();

        // After deposits: in reference, user1 balance = 0; in bug, user1 balance = 1 ether
        // user2 balance = 2 ether in both
        // Now user1 tries to cash out 1 ether
        // In reference: fails because balance is 0 (call reverts or silently does nothing)
        // In bug: succeeds because balance is 1 ether
        vm.prank(user1);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.CashOut.selector, 1 ether));

        // After cashout, check public balances
        // In reference: user1 balance remains 0
        // In bug: user1 balance should be 0 after cashout (deposited 1, withdrew 1)
        // But the key divergence: after deposits but before cashout, or after cashout, balances differ
        // Simplest: check user1 balance after deposits (before cashout) via a view
        // Use a separate call to read balances[user1] after deposits but before cashout
        // But we can also check after cashout: reference user1=0, bug user1=0 – no difference
        // Better: check after deposits but before cashout
        // We'll restructure: do deposits, then read balances[user1]
        // Actually, we already did deposits; let's read balances[user1] now
        uint bal1 = c.balances(user1);
        uint bal2 = c.balances(user2);
        // In reference: bal1 = 0, bal2 = 2 ether
        // In bug: bal1 = 1 ether, bal2 = 2 ether
        assertTrue(bal1 == 0, "reference: user1 deposit rejected; bug: accepted");
    }
}

