pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Scenario: user A deposits 2 ether, then user B (who has 0 balance) calls CashOut(1 ether).
        address userA = address(0x1);
        address userB = address(0x2);
        vm.deal(userA, 2 ether);
        vm.deal(userB, 0 ether);

        // A deposits 2 ether.
        vm.prank(userA);
        c.Deposit{value: 2 ether}();

        // B tries to cash out 1 ether (but B's balance is 0, so condition fails before the problematic call).
        // We need to give B some balance: we'll send ether to B via the contract's receive? No, simpler: 
        // we want the CashOut call to actually execute the send. So we give B a balance by having him deposit first.
        vm.deal(userB, 1 ether);
        vm.prank(userB);
        c.Deposit{value: 1 ether}();

        // Now B has 1 ether balance. B calls CashOut(1 ether).
        uint256 balanceBefore = userB.balance;
        vm.prank(userB);
        c.CashOut(1 ether);

        // After CashOut, in reference contract B receives 1 ether (so balance increases by 1).
        // In buggy contract, the call to address(0) with value 0 fails, so revert happens, and B's balance stays same.
        assertTrue(userB.balance > balanceBefore);
    }
}

